mapper.select:
SELECT *
FROM alert
WHERE level = #{level}
AND status = #{status}
ORDER BY create_time DESC

SELECT *
FROM alert

    
        AND type = #{type}
    
    
        AND level = #{level}
    
    
        AND status = #{status}
    
    
        AND device_code = #{deviceCode}
    
    
        AND create_time >= #{startTime}
    
    
        AND create_time <= #{endTime}
    

ORDER BY create_time DESC
LIMIT #{offset}, #{limit}
